-- Generated by app/scripts/document_analytical_foundation.py from the metric registry.
-- Local SQLite only. Bind ? parameters in their declared order.
-- Requires analytical connection UDFs including AUDIT_QUALIFIED / AUDIT_LINEAGE.
-- Review/internal validation only: public consumers use Analytics.query for disclosure control.

-- metric_id: perumahan.ownership_coverage
-- bindings: [1, 2, 3, 4, 5]
SELECT COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND e."status_kepemilikan" IN (?,?,?,?,?) THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT "__version_normalized","assignment_id","status_kepemilikan" FROM "mart_perumahan" LIMIT -1 OFFSET 0) e WHERE 1=1;

-- metric_id: perumahan.ownership_distribution
-- bindings: []
SELECT e."status_kepemilikan",COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND 1=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT "__version_normalized","assignment_id","status_kepemilikan" FROM "mart_perumahan" LIMIT -1 OFFSET 0) e WHERE 1=1 GROUP BY e."status_kepemilikan";
